// Subscribe once, for example in the form constructor:
dgvCustomers.CellClick += dgvCustomers_CellClick;

private void dgvCustomers_CellClick(object sender, DataGridViewCellEventArgs e)
{
    if (e.RowIndex >= 0)
    {
        string name = dgvCustomers.Rows[e.RowIndex].Cells["Name"].Value?.ToString();
        lblSelected.Text = "Selected: " + name;
    }
}

// Subscribe once, for example in the form constructor:
dgvCustomers.CellValueChanged += dgvCustomers_CellValueChanged;

private void dgvCustomers_CellValueChanged(object sender, DataGridViewCellEventArgs e)
{
    if (e.RowIndex >= 0)
    {
        lblStatus.Text = "Row " + (e.RowIndex + 1) + " was edited";
    }
}

// Subscribe once, for example in the form constructor:
dgvCustomers.CellEndEdit += dgvCustomers_CellEndEdit;

private void dgvCustomers_CellEndEdit(object sender, DataGridViewCellEventArgs e)
{
    var cell = dgvCustomers.Rows[e.RowIndex].Cells[e.ColumnIndex];
    if (cell.Value == null || cell.Value.ToString().Trim().Length == 0)
    {
        cell.ErrorText = "A value is required.";
    }
    else
    {
        cell.ErrorText = string.Empty;
    }
}

// Subscribe once, for example in the form constructor:
dgvCustomers.SelectionChanged += dgvCustomers_SelectionChanged;

private void dgvCustomers_SelectionChanged(object sender, EventArgs e)
{
    btnDelete.Enabled = dgvCustomers.SelectedRows.Count > 0;
}

// Subscribe once, for example in the form constructor:
dgvCustomers.DataError += dgvCustomers_DataError;

private void dgvCustomers_DataError(object sender, DataGridViewDataErrorEventArgs e)
{
    MessageBox.Show("Invalid value: " + e.Exception.Message);
    e.ThrowException = false;
}

// Subscribe once, for example in the form constructor:
dgvCustomers.CellFormatting += dgvCustomers_CellFormatting;

private void dgvCustomers_CellFormatting(object sender, DataGridViewCellFormattingEventArgs e)
{
    if (dgvCustomers.Columns[e.ColumnIndex].Name == "Balance" && e.Value is decimal balance && balance < 0)
    {
        e.CellStyle.ForeColor = Color.Firebrick;
    }
}

// Subscribe once, for example in the form constructor:
bsCustomers.CurrentChanged += bsCustomers_CurrentChanged;
// assumes a Customer class with a Name property

private void bsCustomers_CurrentChanged(object sender, EventArgs e)
{
    lblCurrent.Text = ((Customer)bsCustomers.Current)?.Name;
}

// Subscribe once, for example in the form constructor:
bsCustomers.PositionChanged += bsCustomers_PositionChanged;

private void bsCustomers_PositionChanged(object sender, EventArgs e)
{
    lblPosition.Text = (bsCustomers.Position + 1) + " of " + bsCustomers.Count;
}

// Subscribe once, for example in the form constructor:
bsCustomers.ListChanged += bsCustomers_ListChanged;

private void bsCustomers_ListChanged(object sender, ListChangedEventArgs e)
{
    lblCount.Text = bsCustomers.Count + " customers";
}

// Subscribe once, for example in the form constructor:
bsCustomers.DataSourceChanged += bsCustomers_DataSourceChanged;

private void bsCustomers_DataSourceChanged(object sender, EventArgs e)
{
    lblStatus.Text = "Data source replaced";
}

// Subscribe once, for example in the form constructor:
bnCustomers.RefreshItems += bnCustomers_RefreshItems;

private void bnCustomers_RefreshItems(object sender, EventArgs e)
{
    btnSave.Enabled = bnCustomers.BindingSource != null && bnCustomers.BindingSource.Count > 0;
}
